"use client";

import * as React from "react";
import { Field, FieldLabel } from "@/components/ui/field";
import { Textarea } from "@/components/ui/textarea";
import { controlStyles, textAreaDefaults } from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

export interface KalosTextAreaProps extends React.ComponentProps<"textarea"> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  optional?: boolean;
  counter?: boolean;
  minRows?: number;
  maxRows?: number;
  onSubmitShortcut?: (value: string) => void;
  resizable?: boolean;
  inputClassName?: string;
}

export function KalosTextArea({
  label, hint, error, optional = false, counter = false,
  minRows = textAreaDefaults.minRows, maxRows = textAreaDefaults.maxRows,
  onSubmitShortcut, resizable = true,
  id, ref, className, inputClassName, value, defaultValue, onChange, onKeyDown,
  disabled, readOnly, required, maxLength, rows, ...props
}: KalosTextAreaProps) {
  const autoId = React.useId();
  const fieldId = id ?? autoId;
  const messageId = `${fieldId}-message`;
  const countId = `${fieldId}-count`;
  const inputRef = React.useRef<HTMLTextAreaElement>(null);
  const manualHeight = React.useRef<number | null>(null);
  const drag = React.useRef<{ id: number; y: number; height: number } | null>(null);
  const [internalValue, setInternalValue] = React.useState(defaultValue ?? "");
  const minimumRows = Math.max(1, Math.floor(rows ?? minRows));
  const maximumRows = Math.max(minimumRows, Math.floor(maxRows));
  const text = String(value ?? internalValue);
  const showCount = counter && maxLength !== undefined && maxLength >= 0;
  const overLimit = showCount && text.length > maxLength;
  const invalid = !!error || overLimit || props["aria-invalid"] === true || props["aria-invalid"] === "true";
  const message = error || hint;
  const describedBy = [props["aria-describedby"], message ? messageId : null, showCount ? countId : null].filter(Boolean).join(" ") || undefined;

  React.useImperativeHandle(ref, () => inputRef.current!, []);

  const fit = React.useCallback(() => {
    const input = inputRef.current;
    if (!input) return;
    const style = getComputedStyle(input);
    const lineHeight = parseFloat(style.lineHeight) || textAreaDefaults.lineHeight;
    const padding = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
    const minimum = minimumRows * lineHeight + padding;
    const maximum = maximumRows * lineHeight + padding;
    input.style.minHeight = `${minimum}px`;
    input.style.maxHeight = `${maximum}px`;
    input.style.height = "0px";
    const height = resizable && manualHeight.current !== null
      ? Math.max(minimum, Math.min(manualHeight.current, maximum))
      : Math.max(minimum, Math.min(input.scrollHeight, maximum));
    input.style.height = `${height}px`;
    input.style.overflowY = input.scrollHeight > height ? "auto" : "hidden";
  }, [minimumRows, maximumRows, resizable]);

  React.useLayoutEffect(() => { fit(); }, [fit, text, inputClassName]);
  React.useEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    let width = input.getBoundingClientRect().width;
    const observer = new ResizeObserver(() => {
      const nextWidth = input.getBoundingClientRect().width;
      if (nextWidth !== width) { width = nextWidth; fit(); }
    });
    observer.observe(input);
    let active = true;
    document.fonts.ready.then(() => { if (active) fit(); });
    return () => { active = false; observer.disconnect(); };
  }, [fit]);
  React.useEffect(() => {
    const input = inputRef.current;
    const form = input?.form;
    if (!input || !form) return;
    let frame = 0;
    const reset = (event: Event) => {
      cancelAnimationFrame(frame);
      // React restores textarea defaults after its reset handlers finish.
      frame = requestAnimationFrame(() => {
        if (event.defaultPrevented) return;
        setInternalValue(input.value);
        manualHeight.current = null;
        fit();
      });
    };
    form.addEventListener("reset", reset);
    return () => { form.removeEventListener("reset", reset); cancelAnimationFrame(frame); };
  }, [fit, props.form]);

  function resize(height: number) {
    const input = inputRef.current;
    if (!input) return;
    manualHeight.current = Math.min(parseFloat(input.style.maxHeight), Math.max(parseFloat(input.style.minHeight), height));
    input.style.height = `${manualHeight.current}px`;
    input.style.overflowY = input.scrollHeight > manualHeight.current ? "auto" : "hidden";
  }

  return <Field data-slot="kalos-text-area" data-invalid={invalid} data-disabled={disabled || undefined} className={cn(controlStyles.textAreaField, className)}>
    {label ? <FieldLabel htmlFor={fieldId} className={controlStyles.label} onClickCapture={event => { event.preventDefault(); event.stopPropagation(); }}>
      {label}{required ? <span aria-hidden="true" className={controlStyles.requiredMark}>*</span> : optional ? <span className={controlStyles.textAreaOptional}>可选</span> : null}
    </FieldLabel> : null}
    <div className={controlStyles.textAreaSurface} data-invalid={invalid} data-disabled={disabled || undefined}>
      <Textarea {...props} id={fieldId} ref={inputRef} rows={minimumRows}
        value={value} defaultValue={defaultValue} disabled={disabled} readOnly={readOnly} required={required} maxLength={maxLength}
        className={cn(controlStyles.textAreaInput, resizable && controlStyles.textAreaWithResize, inputClassName)}
        aria-invalid={invalid || props["aria-invalid"]} aria-describedby={describedBy}
        aria-keyshortcuts={onSubmitShortcut ? "Meta+Enter Control+Enter" : props["aria-keyshortcuts"]}
        onChange={event => { setInternalValue(event.target.value); onChange?.(event); }}
        onKeyDown={event => {
          onKeyDown?.(event);
          if (!event.defaultPrevented && !event.nativeEvent.isComposing && !event.repeat && !disabled && !readOnly && event.key === "Enter" && (event.metaKey || event.ctrlKey) && onSubmitShortcut) {
            event.preventDefault();
            onSubmitShortcut(event.currentTarget.value);
          }
        }}
      />
      {resizable && !disabled ? <button type="button" className={controlStyles.textAreaResize} aria-label="调整文本域高度" aria-controls={fieldId} title="拖动调整高度，或使用上下方向键"
        onPointerDown={event => {
          if (!event.isPrimary || event.button !== 0 || !inputRef.current) return;
          event.preventDefault();
          event.currentTarget.focus({ preventScroll: true });
          event.currentTarget.setPointerCapture(event.pointerId);
          drag.current = { id: event.pointerId, y: event.clientY, height: inputRef.current.getBoundingClientRect().height };
        }}
        onPointerMove={event => { if (drag.current?.id === event.pointerId) resize(drag.current.height + event.clientY - drag.current.y); }}
        onPointerUp={event => { if (drag.current?.id === event.pointerId) { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); } }}
        onPointerCancel={() => { drag.current = null; }} onLostPointerCapture={() => { drag.current = null; }}
        onKeyDown={event => {
          const input = inputRef.current;
          if (!input || !["ArrowUp", "ArrowDown", "Home"].includes(event.key)) return;
          event.preventDefault();
          const step = (parseFloat(getComputedStyle(input).lineHeight) || textAreaDefaults.lineHeight) * (event.shiftKey ? 5 : 1);
          resize(event.key === "Home" ? 0 : input.getBoundingClientRect().height + (event.key === "ArrowDown" ? step : -step));
        }}
      ><svg viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="m3 9 6-6M7 9l2-2" stroke="currentColor" strokeLinecap="round" /></svg></button> : null}
    </div>
    {message || showCount ? <div className={controlStyles.textAreaMeta}>
      {message ? <div id={messageId} role={error ? "alert" : undefined} className={error ? controlStyles.formError : controlStyles.formStatus}>{message}</div> : null}
      {showCount ? <span id={countId} className={cn(controlStyles.textAreaCount, overLimit && controlStyles.formError)}>{text.length.toLocaleString("zh-CN")} / {maxLength.toLocaleString("zh-CN")}</span> : null}
    </div> : null}
  </Field>;
}

import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";

export function Textarea({ className, ...props }: ComponentProps<"textarea">) {
  return <textarea data-slot="textarea" className={cn("block w-full min-w-0 outline-none", className)} {...props} />;
}

"use client";

import { Button } from "@base-ui/react/button";
import { Progress } from "@base-ui/react/progress";
import { cn } from "cn";
import { Check, File, RotateCw, Upload, X } from "lucide-react";
import { AnimatePresence, motion, useIsPresent } from "motion/react";
import { useEffect, useEffectEvent, useId, useRef, useState, type DragEvent } from "react";
import { dropzoneCss, dropzoneDefaults, dropzoneStyleHref } from "@/components/ui/kalos-dropzone-styles";
import { KalosButton } from "./kalos-button";

export type KalosUploadItem = {
  id: string;
  name: string;
  size: number;
  status: "uploading" | "done" | "error";
  progress: number;
  error?: string;
  file?: File;
};

export type KalosDropzoneProps = {
  variant?: "area" | "button";
  accept?: string[];
  maxSize?: number;
  onUpload?: (file: File, onProgress: (progress: number) => void, signal: AbortSignal) => Promise<void>;
  onChange?: (items: KalosUploadItem[]) => void;
  hint?: string;
  autoplay?: boolean;
  className?: string;
};

type Sample = {
  name: string;
  size: number;
  duration: number;
  fails?: boolean;
};

type Entry = {
  item: KalosUploadItem;
  sample?: Sample;
  retryable: boolean;
  remaining?: number;
  delay: number;
};

const megabyte = 1024 ** 2;
const defaultMaxSize = 25 * megabyte;
const sizeFormat = new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 1 });
const samples: Sample[] = [
  { name: "产品手册.pdf", size: Math.round(4.2 * megabyte), duration: 3600 },
  { name: "封面预览.png", size: Math.round(2.6 * megabyte), duration: 2750 },
  { name: "物料清单.xlsx", size: Math.round(1.3 * megabyte), duration: 3100, fails: true },
  { name: "会议纪要.docx", size: Math.round(1.8 * megabyte), duration: 3200 },
  { name: "演示录屏.mp4", size: 32 * megabyte, duration: 0 },
];

function formatSize(bytes: number) {
  if (bytes >= 1024 ** 3) return `${sizeFormat.format(bytes / 1024 ** 3)}\u00a0GB`;
  if (bytes >= megabyte) return `${sizeFormat.format(bytes / megabyte)}\u00a0MB`;
  if (bytes >= 1024) return `${sizeFormat.format(bytes / 1024)}\u00a0KB`;
  return `${sizeFormat.format(bytes)}\u00a0B`;
}

function fileTone(name: string) {
  const extension = name.split(".").pop()?.toLowerCase();
  switch (extension) {
    case "pdf": return "document";
    case "png": case "jpg": case "jpeg": case "webp": case "gif": case "svg":
      return "image";
    case "xls": case "xlsx": case "csv":
      return "sheet";
    case "doc": case "docx":
      return "word";
    case "mp4": case "mov": case "webm":
      return "video";
    default: return "file";
  }
}

function simulateUpload(
  duration: number,
  report: (progress: number) => void,
  signal: AbortSignal,
  fails: boolean,
) {
  return new Promise<void>((resolve, reject) => {
    const started = performance.now();
    const stop = () => clearInterval(timer);
    const abort = () => {
      stop();
      reject(signal.reason);
    };
    const threshold = fails ? 0.68 : 1;
    const timer = setInterval(() => {
      const progress = Math.min(threshold, (performance.now() - started) / duration);
      report(progress);
      if (progress < threshold) return;
      stop();
      signal.removeEventListener("abort", abort);
      if (fails) reject(new Error("连接中断"));
      else resolve();
    }, 80);
    signal.addEventListener("abort", abort, { once: true });
  });
}

function UploadRow({
  entry,
  onRemove,
  onRetry,
}: {
  entry: Entry;
  onRemove: (button: HTMLButtonElement) => void;
  onRetry: (button: HTMLButtonElement) => void;
}) {
  const { item, retryable, remaining, delay } = entry;
  const present = useIsPresent();
  const { name, size, status, progress, error } = item;
  const showProgress = status === "uploading" || retryable;
  const sizeLabel = status === "uploading"
    ? `${formatSize(Math.round(size * progress))} / ${formatSize(size)}`
    : formatSize(size);

  return <motion.li
    className="kalos-dropzone-row"
    initial={{ height: 0, opacity: 0, y: -4 }}
    animate={{ height: "auto", opacity: 1, y: 0 }}
    exit={{ height: 0, opacity: 0, y: -3 }}
    transition={{ duration: dropzoneDefaults.duration / 1000, ease: [...dropzoneDefaults.ease], delay: present ? delay : 0 }}
    inert={!present}
    aria-hidden={present ? undefined : true}
    data-status={status}
  >
    <div className="kalos-dropzone-row-content">
      <span className="kalos-dropzone-mark" data-tone={fileTone(name)} aria-hidden="true"><File /></span>
      <div className="kalos-dropzone-file">
        <div className="kalos-dropzone-file-heading">
          <span className="kalos-dropzone-name" title={name}>{name}</span>
          {status === "done" && <span className="kalos-dropzone-done"><Check aria-hidden="true" /><span className="kalos-dropzone-sr">已上传</span></span>}
        </div>
        <div className="kalos-dropzone-meta">
          <span>{status === "error" ? error : sizeLabel}</span>
          {status === "uploading" && remaining != null && <span>约 {remaining} 秒</span>}
        </div>
        <Progress.Root
          value={Math.round(progress * 100)}
          aria-label={`${name}上传进度`}
          aria-hidden={!showProgress}
          data-visible={showProgress ? "" : undefined}
          className="kalos-dropzone-progress"
        >
          <Progress.Track className="kalos-dropzone-track"><Progress.Indicator className="kalos-dropzone-indicator" /></Progress.Track>
        </Progress.Root>
      </div>
      <div className="kalos-dropzone-actions">
        {retryable && <Button type="button" aria-label={`重试 ${name}`} title="重试" onClick={event => onRetry(event.currentTarget)}><RotateCw aria-hidden="true" /></Button>}
        <Button type="button" data-remove="" aria-label={`移除 ${name}`} title="移除" onClick={event => onRemove(event.currentTarget)}><X aria-hidden="true" /></Button>
      </div>
    </div>
  </motion.li>;
}

export function KalosDropzone({
  variant = "area",
  accept,
  maxSize = defaultMaxSize,
  onUpload,
  onChange,
  hint,
  autoplay = false,
  className,
}: KalosDropzoneProps) {
  const titleId = useId();
  const hintId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const entriesRef = useRef<Entry[]>([]);
  const onChangeRef = useRef(onChange);
  const attempts = useRef(new Map<string, AbortController>());
  const nextId = useRef(0);
  const dragDepth = useRef(0);
  const demoInterrupted = useRef(false);
  const [entries, setEntries] = useState<Entry[]>([]);
  const [dragCount, setDragCount] = useState<number | null>(null);
  const [demoDrag, setDemoDrag] = useState(false);
  const [announcements, setAnnouncements] = useState<{ id: number; text: string }[]>([]);
  const allowed = accept?.map(type => type.trim().toLowerCase()).filter(Boolean) ?? [];
  const constraints = hint ?? [
    allowed.length ? allowed.map(type => type.startsWith(".") ? type.slice(1).toUpperCase() : type).join("、") : "",
    Number.isFinite(maxSize) ? `单文件上限 ${formatSize(maxSize)}` : "",
  ].filter(Boolean).join(" · ");
  const describedBy = constraints ? hintId : undefined;
  const activeCount = dragCount ?? (autoplay && demoDrag ? samples.length : null);
  const uploading = entries.filter(({ item }) => item.status === "uploading").length;
  const failed = entries.filter(({ item }) => item.status === "error").length;
  const done = entries.length - uploading - failed;
  const uploadedBytes = entries.reduce((sum, { item }) => sum + item.size * item.progress, 0);
  const uploadableBytes = entries.reduce((sum, { item, retryable }) => sum + (item.status !== "error" || retryable ? item.size : 0), 0);

  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  useEffect(() => {
    const running = attempts.current;
    return () => {
      for (const controller of running.values()) controller.abort();
      running.clear();
    };
  }, []);

  function publish(next: Entry[]) {
    entriesRef.current = next;
    setEntries(next);
    onChangeRef.current?.(next.map(({ item }) => ({ ...item })));
  }

  function announce(text: string) {
    const id = ++nextId.current;
    setAnnouncements(current => [...current.slice(-7), { id, text }]);
  }

  function replace(id: string, update: (entry: Entry) => Entry) {
    publish(entriesRef.current.map(entry => entry.item.id === id ? update(entry) : entry));
  }

  async function upload(entry: Entry, retry = false) {
    const { item: { id, file, name, size }, sample } = entry;
    const controller = new AbortController();
    const { signal } = controller;
    attempts.current.set(id, controller);
    const started = performance.now();
    let latest = 0;
    const report = (progress: number) => {
      if (signal.aborted || attempts.current.get(id) !== controller || !Number.isFinite(progress)) return;
      const current = Math.min(1, Math.max(latest, progress));
      if (current === latest) return;
      latest = current;
      const remaining = current < 1 ? Math.max(1, Math.ceil((performance.now() - started) * (1 - current) / current / 1000)) : undefined;
      replace(id, row => ({ ...row, remaining, item: { ...row.item, progress: current } }));
    };

    try {
      if (file && onUpload) await onUpload(file, report, signal);
      else {
        const duration = sample?.duration ?? Math.min(4200, 900 + size / megabyte * 110);
        await simulateUpload(duration, report, signal, Boolean(sample?.fails && !retry));
      }
    } catch (error) {
      if (signal.aborted || attempts.current.get(id) !== controller) return;
      attempts.current.delete(id);
      const message = (error instanceof Error ? error.message : typeof error === "string" ? error : "") || "上传失败";
      replace(id, row => ({ ...row, retryable: true, item: { ...row.item, status: "error", error: message } }));
      announce(`${name}，${message}`);
      return;
    }

    if (signal.aborted || attempts.current.get(id) !== controller) return;
    attempts.current.delete(id);
    replace(id, row => ({ ...row, item: { ...row.item, status: "done", progress: 1 } }));
    announce(`${name}已上传`);
  }

  function addFiles(files: File[], demoFiles: Sample[] = []) {
    const sources = [...files.map(file => ({ file })), ...demoFiles.map(sample => ({ sample }))];
    if (!sources.length) return;

    const added = sources.map((source, index): Entry => {
      const file = "file" in source ? source.file : undefined;
      const sample = "sample" in source ? source.sample : undefined;
      const { name, size } = "file" in source ? source.file : source.sample;
      const type = file?.type.toLowerCase();
      const accepted = !file || !allowed.length || allowed.some(pattern => {
        if (pattern.startsWith(".")) return name.toLowerCase().endsWith(pattern);
        if (pattern.endsWith("/*")) return type?.startsWith(pattern.slice(0, -1));
        return type === pattern;
      });
      const limit = sample ? defaultMaxSize : maxSize;
      let error: string | undefined;
      if (!accepted) error = "不支持此文件类型";
