.kalos-otp[data-status="success"] .kalos-otp__success {
  width: min(100%, var(--otp-pill-width));
  height: 34px;
  border-radius: 99px;
  opacity: 1;
  transition: opacity 200ms ease 100ms, width var(--otp-morph) var(--otp-ease) 160ms,
    height var(--otp-morph) var(--otp-ease) 160ms, border-radius var(--otp-morph) var(--otp-ease) 160ms;
