}
.kalos-otp__success-content > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kalos-otp__success-content svg { width: 16px; height: 16px; flex: none; }
.kalos-otp__success-content path { stroke-dasharray: 24; stroke-dashoffset: 24; }
.kalos-otp[data-status="success"] .kalos-otp__success-content path {
