.kalos-otp__sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@keyframes kalos-otp-digit-in { from { opacity: 0; transform: translateY(4px) scale(.75); } to { opacity: 1; transform: none; } }
@keyframes kalos-otp-digit-out { to { opacity: 0; transform: translateY(-4px) scale(.85); } }
@keyframes kalos-otp-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }
@keyframes kalos-otp-shimmer { 0% { transform: translateX(-120%); } 55%, 100% { transform: translateX(120%); } }
@keyframes kalos-otp-shake {
  12% { transform: translateX(-5px); }
  29% { transform: translateX(4px); }
