export const decisionDefaults = {"radius":12,"rowRadius":6,"narrowWidth":420,"foldDuration":420,"pageDuration":200,"pulseDuration":400,"ease":[0.23,1,0.32,1]} as const;
export const decisionCardStyleHref = "kalos-decision-card-2cd17a1309a5";
export const decisionCardCss = ".kalos-decision-card{font-family:Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;font-size:13px;line-height:20px;--kd-surface:var(--card, #ffffff);--kd-ink:var(--card-foreground, rgba(0, 0, 0, 0.88));--kd-muted:var(--muted-foreground, rgba(0, 0, 0, 0.61));--kd-hover:var(--accent, rgba(0, 0, 0, 0.045));--kd-soft:var(--muted, rgba(0, 0, 0, 0.04));--kd-edge:var(--border, #00000014);--kd-focus:rgba(0, 96, 226, 0.765);--kd-shadow:0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 1px 2px rgba(0, 0, 0, 0.035);--kd-warn:#9c5d15;--kd-warn-wash:#fef2e3;--kd-highlight-color:rgba(0, 0, 0, 0.045);--kd-highlight-ease:cubic-bezier(0.22, 1, 0.36, 1);--kd-radius:12px;--kd-row-radius:6px;--kd-highlight-radius:6px;--kd-highlight-duration:180ms}
